// World layout, rendering resolution and the shared palette.
// The palette mirrors assets/data/palette.json (generated by the asset pipeline).

/** Size of one pathing/build cell in world pixels. */
export const CELL = 16;
/** Map size in cells. The keep sits on the far left; the crusade enters from the right. */
export const MW = 96, MH = 40;
export const WW = MW * CELL, WH = MH * CELL;

/** Target internal resolution (world pixels visible). The game picks the largest
 *  integer zoom that keeps at least this much of the world on screen. */
export const VIEW_TARGET_W = 480, VIEW_TARGET_H = 270;

/** The keep's gatehouse in the fortress's curtain wall (src/data/fortress.ts): the crusade's target,
 *  the flow-field goal and the anchor for spawns and spells. */
export const KEEP = { x: 208, y: 408, x0: 160, x1: 256, y0: 384, y1: 432, cx0: 10, cx1: 15, cy0: 24, cy1: 26 };
/** The Soul Well stands behind the walls, between the Curtain and the Bulwark, north of the gate. */
export const WELL_POS = { x: 352, y: 290, cx0: 21, cx1: 23, cy0: 16, cy1: 18 };
/** Where idle undead form up: a line in front of the keep gate. */
export const GUARD_LINE_X = 400;

